import java.util.Scanner;

public class Main {
    static int[] weights;
    static long[] carried;
    static int rounds;
    static long total = 0;

    static synchronized void addWeight(int index) {
        total = total + weights[index];
        carried[index] = carried[index] + weights[index];
    }

    static class Loader extends Thread {
        private int index;

        Loader(int index) {
            this.index = index;
        }

        public void run() {
            for (int r = 0; r < rounds; r++) {
                addWeight(index);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        rounds = sc.nextInt();
        weights = new int[m];
        carried = new long[m];
        for (int i = 0; i < m; i++) {
            weights[i] = sc.nextInt();
        }
        Loader[] loaders = new Loader[m];
        for (int i = 0; i < m; i++) {
            loaders[i] = new Loader(i);
            loaders[i].start();
        }
        for (int i = 0; i < m; i++) {
            loaders[i].join();
        }
        for (int i = 0; i < m; i++) {
            System.out.println("Loader " + (i + 1) + " carried: " + carried[i]);
        }
        System.out.println("Total weight: " + total);
    }
}

import java.util.Scanner;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static int revenue = 0;
    static int passes = 0;
    static int fee;
    static int trips;
    static ReentrantLock gate = new ReentrantLock();

    static void collect() {
        gate.lock();
        try {
            revenue = revenue + fee;
            passes = passes + 1;
        } finally {
            gate.unlock();
        }
    }

    static class Car extends Thread {
        public void run() {
            for (int i = 0; i < trips; i++) {
                collect();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        trips = sc.nextInt();
        fee = sc.nextInt();
        Car[] cars = new Car[m];
        for (int i = 0; i < m; i++) {
            cars[i] = new Car();
            cars[i].start();
        }
        for (int i = 0; i < m; i++) {
            cars[i].join();
        }
        System.out.println("Total revenue: " + revenue);
        System.out.println("Vehicles served: " + passes);
    }
}

import java.util.Scanner;

public class Main {
    static int items;
    static long processed;

    static class StageTask implements Runnable {
        public void run() {
            long s = 0;
            for (int i = 1; i <= items; i++) {
                s = s + i;
            }
            processed = s;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        int[] loads = new int[k];
        for (int i = 0; i < k; i++) {
            loads[i] = sc.nextInt();
        }
        Runnable[] pipeline = new Runnable[k];
        for (int i = 0; i < k; i++) {
            items = loads[i];
            pipeline[i] = new StageTask();
            Thread worker = new Thread(pipeline[i]);
            worker.start();
            worker.join();
            System.out.println("Stage " + (i + 1) + " done: " + processed);
        }
    }
}

import java.util.Scanner;

public class Main {
    static int[][] jobs;
    static long[] results;

    static class Machine extends Thread {
        private int index;

        Machine(int index) {
            this.index = index;
        }

        public void run() {
            long p = 1;
            for (int c = 0; c < jobs[index].length; c++) {
                p = p * jobs[index][c];
            }
            results[index] = p;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        jobs = new int[k][2];
        results = new long[k];
        for (int i = 0; i < k; i++) {
            jobs[i][0] = sc.nextInt();
            jobs[i][1] = sc.nextInt();
        }
        Machine[] machines = new Machine[k];
        for (int i = 0; i < k; i++) {
            machines[i] = new Machine(i);
            machines[i].start();
        }
        long grand = 1;
        for (int i = 0; i < k; i++) {
            machines[i].join();
            grand = grand * results[i];
            System.out.println("Machine " + (i + 1) + ": " + results[i]);
        }
        System.out.println("Grand product: " + grand);
    }
}

import java.util.Scanner;

public class Main {
    static String outcome;

    static class Downloader extends Thread {
        public void run() {
            try {
                Thread.sleep(20);
                outcome = "Download completed";
            } catch (InterruptedException e) {
                outcome = "Download cancelled";
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        String job = sc.next();
        Downloader worker = new Downloader();
        worker.setName(job);
        worker.interrupt();
        worker.start();
        worker.join();
        System.out.println("Job: " + worker.getName());
        System.out.println("Outcome: " + outcome);
    }
}

import java.util.Scanner;

public class Main {
    static int jobs;
    static long total;

    static class StateWorker extends Thread {
        public void run() {
            System.out.println("Worker sees before sleep: " + Thread.currentThread().getState());
            try {
                Thread.sleep(15);
            } catch (InterruptedException e) {
                // nobody interrupts this worker
            }
            System.out.println("Worker sees after sleep: " + Thread.currentThread().getState());
            long s = 0;
            for (int i = 1; i <= jobs; i++) {
                s = s + i;
            }
            total = s;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        jobs = sc.nextInt();
        StateWorker worker = new StateWorker();
        System.out.println("Main sees before start: " + worker.getState());
        worker.start();
        worker.join();
        System.out.println("Main sees after join: " + worker.getState());
        System.out.println("Sum: " + total);
    }
}

import java.util.Scanner;

public class Main {
    static int[] balances;
    static int[] fromIds;
    static int[] toIds;
    static int[] amounts;

    static synchronized void doTransfer(int from, int to, int amount) {
        balances[from] = balances[from] - amount;
        balances[to] = balances[to] + amount;
    }

    static class TransferThread extends Thread {
        private int index;

        TransferThread(int index) {
            this.index = index;
        }

        public void run() {
            doTransfer(fromIds[index] - 1, toIds[index] - 1, amounts[index]);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        balances = new int[n];
        for (int i = 0; i < n; i++) {
            balances[i] = sc.nextInt();
        }
        int t = sc.nextInt();
        fromIds = new int[t];
        toIds = new int[t];
        amounts = new int[t];
        for (int i = 0; i < t; i++) {
            fromIds[i] = sc.nextInt();
            toIds[i] = sc.nextInt();
            amounts[i] = sc.nextInt();
        }
        TransferThread[] threads = new TransferThread[t];
        for (int i = 0; i < t; i++) {
            threads[i] = new TransferThread(i);
            threads[i].start();
        }
        for (int i = 0; i < t; i++) {
            threads[i].join();
        }
        for (int i = 0; i < n; i++) {
            System.out.println("Account " + (i + 1) + ": " + balances[i]);
        }
    }
}

import java.util.Scanner;

public class Main {
    static int[] consumed;
    static int consumedCount = 0;

    static class Buffer {
        private int[] slots;
        private int count = 0;
        private int head = 0;
        private int tail = 0;

        Buffer(int cap) {
            slots = new int[cap];
        }

        synchronized void put(int item) {
            while (count == slots.length) {
                try {
                    wait();
                } catch (InterruptedException e) {
                    // stay in the loop and re-check the buffer
                }
            }
            slots[tail] = item;
            tail = (tail + 1) % slots.length;
            count = count + 1;
            notifyAll();
        }

        synchronized int take() {
            while (count == 0) {
                try {
                    wait();
                } catch (InterruptedException e) {
                    // stay in the loop and re-check the buffer
                }
            }
            int item = slots[head];
            head = (head + 1) % slots.length;
            count = count - 1;
            consumed[consumedCount] = item;
            consumedCount = consumedCount + 1;
            notifyAll();
            return item;
        }
    }

    static class Producer extends Thread {
        private Buffer buffer;
        private int[] items;

        Producer(Buffer buffer, int[] items) {
            this.buffer = buffer;
            this.items = items;
        }

        public void run() {
            for (int i = 0; i < items.length; i++) {
                buffer.put(items[i]);
            }
        }
    }

    static class Consumer extends Thread {
        private Buffer buffer;
        private int total;

        Consumer(Buffer buffer, int total) {
            this.buffer = buffer;
            this.total = total;
        }

        public void run() {
            for (int i = 0; i < total; i++) {
                buffer.take();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int cap = sc.nextInt();
        int k = sc.nextInt();
        int[] items = new int[k];
        for (int i = 0; i < k; i++) {
            items[i] = sc.nextInt();
        }
        consumed = new int[k];
        Buffer buffer = new Buffer(cap);
        Consumer c = new Consumer(buffer, k);
        Producer p = new Producer(buffer, items);
        c.start();
        p.start();
        p.join();
        c.join();
        for (int i = 0; i < k; i++) {
            System.out.println("Consumed: " + consumed[i]);
        }
        System.out.println("Total consumed: " + consumedCount);
    }
}

import java.util.Scanner;

public class Main {
    static int[] data;
    static int chunkSize;
    static long[] chunkSums;
    static long grandTotal = 0;

    static synchronized void merge(int index, long sum) {
        chunkSums[index] = sum;
        grandTotal = grandTotal + sum;
    }

    static class BatchTask implements Runnable {
        private int index;

        BatchTask(int index) {
            this.index = index;
        }

        public void run() {
            long s = 0;
            int start = index * chunkSize;
            for (int j = 0; j < chunkSize; j++) {
                s = s + data[start + j];
            }
            merge(index, s);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        chunkSize = sc.nextInt();
        int n = k * chunkSize;
        data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = sc.nextInt();
        }
        chunkSums = new long[k];
        Thread[] workers = new Thread[k];
        for (int i = 0; i < k; i++) {
            workers[i] = new Thread(new BatchTask(i));
            workers[i].start();
        }
        for (int i = 0; i < k; i++) {
            workers[i].join();
        }
        for (int i = 0; i < k; i++) {
            System.out.println("Chunk " + (i + 1) + ": " + chunkSums[i]);
        }
        System.out.println("Grand total: " + grandTotal);
    }
}

import java.util.Scanner;

public class Main {
    static int[] data;
    static int chunkSize;
    static int[] mins;
    static int[] maxs;

    static class MinMaxWorker extends Thread {
        private int index;

        MinMaxWorker(int index) {
            this.index = index;
        }

        public void run() {
            int start = index * chunkSize;
            int lo = data[start];
            int hi = data[start];
            for (int j = 1; j < chunkSize; j++) {
                int v = data[start + j];
                if (v < lo) {
                    lo = v;
                }
                if (v > hi) {
                    hi = v;
                }
            }
            mins[index] = lo;
            maxs[index] = hi;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        chunkSize = sc.nextInt();
        int n = k * chunkSize;
        data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = sc.nextInt();
        }
        mins = new int[k];
        maxs = new int[k];
        MinMaxWorker[] workers = new MinMaxWorker[k];
        for (int i = 0; i < k; i++) {
            workers[i] = new MinMaxWorker(i);
            System.out.println("Worker " + (i + 1) + " state before start: " + workers[i].getState());
            workers[i].start();
        }
        for (int i = 0; i < k; i++) {
            workers[i].join();
        }
        int gmin = mins[0];
        int gmax = maxs[0];
        for (int i = 0; i < k; i++) {
            System.out.println("Worker " + (i + 1) + " state after join: " + workers[i].getState());
            System.out.println("Worker " + (i + 1) + " range: min " + mins[i] + " max " + maxs[i]);
            if (mins[i] < gmin) {
                gmin = mins[i];
            }
            if (maxs[i] > gmax) {
                gmax = maxs[i];
            }
        }
        System.out.println("Global min: " + gmin);
        System.out.println("Global max: " + gmax);
    }
}
